use kino_core::{color::pipeline::{Pipeline,rgba16},effects::Frame,commands::{Session,dispatch},model::Project};use serde_json::json;
#[test]fn old_project_default(){let mut v=serde_json::to_value(Project::default()).unwrap();v.as_object_mut().unwrap().remove("color_pipeline");let p:Project=serde_json::from_value(v).unwrap();assert!(!p.color_pipeline.enabled)}
#[test]fn pipeline_settings_invalid(){for p in [Pipeline{enabled:true,working_gamut:99,..Default::default()},Pipeline{reference_white:0.,..Default::default()},Pipeline{input_transfer:99,..Default::default()}]{assert!(p.validate().is_err())}}
#[test]fn rgba16_keeps_precision(){let f=Frame{w:1024,h:1,d:(0..1024).flat_map(|i|[i as f32/1023.,0.,0.,1.]).collect()};let b=rgba16(&f).unwrap();let vals:std::collections::HashSet<_>=b.chunks_exact(8).map(|v|u16::from_le_bytes([v[0],v[1]])).collect();assert_eq!(vals.len(),1024);assert!(rgba16(&Frame{w:1,h:1,d:vec![f32::NAN;4]}).is_err())}
#[test]fn working_composite_linear(){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16,"fps":25})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":0}})).unwrap();for color in [[0.,0.,0.],[1.,1.,1.]]{let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].as_str().unwrap().to_string();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":color,"start":0,"duration":1})).unwrap()["clip_id"].as_str().unwrap().to_string();if color[0]>0.{dispatch(&mut s,"set_property",&json!({"clip_id":c,"property":"opacity","value":0.5})).unwrap();}}let mut f=kino_core::render::render_frame(&s.project,0.,&s.cache).unwrap();assert!((f.d[0]-0.5).abs()<1e-6);kino_core::color::pipeline::output(&s.project,&mut f).unwrap();assert!((f.d[0]-0.7353569).abs()<1e-6)}
#[test]fn integer_linear_fit_optin(){use std::io::Write;use std::process::{Command,Stdio};let path=std::env::temp_dir().join(format!("kino-int-fit-{}.png",std::process::id()));let mut ch=Command::new("ffmpeg").args(["-v","error","-y","-f","rawvideo","-pix_fmt","rgba64le","-s","32x16","-i","-","-frames:v","1",path.to_str().unwrap()]).stdin(Stdio::piped()).spawn().unwrap();let bytes:Vec<u8>=(0..512).flat_map(|i|{let v=if i%2==0{0u16}else{65535};[v,v,v,65535].into_iter().flat_map(u16::to_le_bytes)}).collect();ch.stdin.take().unwrap().write_all(&bytes).unwrap();assert!(ch.wait().unwrap().success());let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16,"fps":25})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"duration":1,"fit":"stretch"})).unwrap()["clip_id"].clone();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"linear_resample":true,"input_transfer":1,"working_gamut":0}})).unwrap();kino_core::render::prepare_at(&s.project,&mut s.cache,Some(0.)).unwrap();assert!(s.cache.frames_of(c.as_str().unwrap()).unwrap().working_linear);let f=kino_core::render::render_frame(&s.project,0.,&s.cache).unwrap();assert!(f.d.chunks_exact(4).all(|px|(px[0]-0.5).abs()<1e-6));dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":0}})).unwrap();assert!(!s.project.color_pipeline.linear_resample);std::fs::remove_file(path).unwrap();}
#[test]fn integer_table_matches_general_transform(){use kino_core::{color::pipeline::{Input16,input},model::Source};let mut s=Session::new();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let id=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","start":0,"duration":1})).unwrap()["clip_id"].as_str().unwrap().to_string();let mut c=s.project.find_clip(&id).unwrap().clone();c.source=Source::Media{asset:"test".into()};let bytes:Vec<u8>=(0..65536u32).flat_map(|i|[i as u16,(65535-i) as u16,(i.wrapping_mul(17)%65536) as u16,32768].into_iter().flat_map(u16::to_le_bytes)).collect();for t in 0..9{for g in [0,3,5,7]{s.project.color_pipeline=Pipeline{enabled:true,input_transfer:t,input_gamut:g,working_gamut:3,reference_white:123.456,..Default::default()};let mut f=Frame{w:65536,h:1,d:bytes.chunks_exact(2).map(|b|u16::from_le_bytes([b[0],b[1]]) as f32/65535.).collect()};input(&s.project,&c,&mut f).unwrap();let d=Input16::new(&s.project,&c).unwrap().decode(&bytes).unwrap();assert_eq!(d,f.d,"transfer{t} gamut{g}");}}}
#[test]fn hostile_rgba16_shape(){for f in [Frame{w:0,h:1,d:vec![]},Frame{w:2,h:1,d:vec![0.;4]},Frame{w:usize::MAX,h:2,d:vec![]}]{assert!(rgba16(&f).is_err());}}
#[test]fn high_export_invalid_preflight(){use kino_core::color::pipeline::export_high;let mut p=Project::default();for (path,format,crf) in [("/tmp/x.mkv","ffv1_16",52),("/tmp/x.mov","garbage",18),("/tmp/x.mp4","ffv1_16",18)]{assert!(export_high(&p,path,format,crf).is_err());}p.width=1;assert!(export_high(&p,"/tmp/x.mp4","hevc10",18).is_err());p.width=2;p.fps=f64::INFINITY;assert!(export_high(&p,"/tmp/x.mkv","ffv1_16",18).is_err());p.fps=25.;assert!(export_high(&p,"/tmp/x.mkv","ffv1_16",18).is_err());}
#[test]fn high_export_short_fixture(){use kino_core::color::pipeline::export_high;let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16,"fps":25})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","start":0,"duration":0.1})).unwrap();let path=std::env::temp_dir().join(format!("kino-guard-export-{}.mkv",std::process::id()));assert!(export_high(&s.project,path.to_str().unwrap(),"ffv1_16",18).is_ok());std::fs::remove_file(path).unwrap();}
